SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for tool
-- ----------------------------
DROP TABLE IF EXISTS `tool`;
CREATE TABLE `tool`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工具名称',
  `display_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '显示名称',
  `description` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工具描述',
  `module` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属模块',
  `json_schema` json NOT NULL COMMENT '参数 JSON Schema (MCP inputSchema)',
  `output_schema` json NOT NULL COMMENT '输出 JSON Schema (MCP outputSchema)',
  `risk_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'low' COMMENT '风险等级: low/medium/high',
  `is_enabled` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用: 1=是 0=否',
  `timeout_seconds` int UNSIGNED NOT NULL DEFAULT 60 COMMENT '工具执行超时 (秒)',
  `strict_mode` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'OpenAI strict 模式: 1=启用 0=禁用',
  `annotations` json NOT NULL COMMENT 'MCP Tool Annotations',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除: 1=是 0=否',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tool_name`(`name` ASC) USING BTREE,
  INDEX `idx_tool_module`(`module` ASC) USING BTREE,
  INDEX `idx_tool_is_deleted_enabled`(`is_deleted` ASC, `is_enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '工具注册表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tool
