INSERT INTO `tool` VALUES (23, 'session_search', '搜索会话记录', '全文搜索历史会话对话记录', 'sessions', '{\"type\": \"object\", \"required\": [\"query\"], \"properties\": {\"limit\": {\"type\": \"integer\", \"default\": 10}, \"query\": {\"type\": \"string\", \"description\": \"搜索关键词\"}, \"session_key\": {\"type\": \"string\", \"description\": \"限定某个会话\"}}}', '{\"type\": \"object\", \"properties\": {\"results\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"properties\": {\"score\": {\"type\": \"number\"}, \"message\": {\"type\": \"string\"}, \"timestamp\": {\"type\": \"string\"}, \"session_key\": {\"type\": \"string\"}}}}}}', 'low', 1, 15, 0, '{\"readOnlyHint\": true, \"openWorldHint\": false, \"idempotentHint\": true, \"destructiveHint\": false, \"version\": \"1.0.0\"}', 0, '2026-06-13 23:33:47', '2026-06-13 23:33:47');
INSERT INTO `tool` VALUES (27, 'web_search', '网页搜索', '通过 SearXNG 搜索互联网获取实时信息，搜索服务不可用时，用web_fetch抓取网页内容。', 'web', '{\"type\": \"object\", \"required\": [\"query\"], \"properties\": {\"query\": {\"type\": \"string\", \"description\": \"搜索关键词\"}, \"max_results\": {\"type\": \"integer\", \"default\": 5, \"description\": \"最大结果数\"}}}', '{\"type\": \"object\", \"properties\": {\"error\": {\"type\": \"string\"}, \"results\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"properties\": {\"url\": {\"type\": \"string\"}, \"title\": {\"type\": \"string\"}, \"snippet\": {\"type\": \"string\"}}}}}}', 'low', 1, 15, 0, '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true, \"destructiveHint\": false, \"version\": \"1.0.0\"}', 0, '2026-06-14 00:09:22', '2026-06-23 03:34:05');
INSERT INTO `tool` VALUES (28, 'execute_code', '执行代码', '在 Docker 沙箱中执行代码（支持 Python/JavaScript，无网络，128MB 内存限制）', 'sandbox', '{\"type\": \"object\", \"required\": [\"language\", \"code\"], \"properties\": {\"code\": {\"type\": \"string\", \"description\": \"要执行的代码\"}, \"language\": {\"enum\": [\"python\", \"javascript\"], \"type\": \"string\", \"description\": \"编程语言\"}}}', '{\"type\": \"object\", \"properties\": {\"error\": {\"type\": \"string\"}, \"stderr\": {\"type\": \"string\"}, \"stdout\": {\"type\": \"string\"}, \"exit_code\": {\"type\": \"integer\"}}}', 'high', 1, 15, 0, '{\"readOnlyHint\": false, \"openWorldHint\": true, \"idempotentHint\": false, \"destructiveHint\": true, \"sandboxHint\": true, \"version\": \"1.0.1\"}', 0, '2026-06-14 00:09:22', '2026-06-14 00:09:22');
INSERT INTO `tool` VALUES (29, 'query_database', '查询数据库', '执行只读 SELECT 查询（自动防注入，禁止写操作，默认 LIMIT 100）', 'database', '{\"type\": \"object\", \"required\": [\"sql\"], \"properties\": {\"sql\": {\"type\": \"string\", \"description\": \"SQL SELECT 查询语句\"}}}', '{\"type\": \"object\", \"properties\": {\"rows\": {\"type\": \"array\"}, \"count\": {\"type\": \"integer\"}, \"error\": {\"type\": \"string\"}, \"columns\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}}}}', 'medium', 1, 15, 0, '{\"readOnlyHint\": true, \"openWorldHint\": false, \"idempotentHint\": false, \"destructiveHint\": false, \"version\": \"1.0.0\"}', 0, '2026-06-14 00:09:22', '2026-06-14 00:09:22');

INSERT INTO `tool` VALUES (30, 'http_request', 'HTTP 请求', '发送 HTTP 请求调用外部 API（GET/POST/PUT/DELETE），支持自定义 Headers 和 Body', 'web', '{"type": "object", "required": ["method", "url"], "properties": {"method": {"enum": ["GET", "POST", "PUT", "DELETE", "PATCH"], "type": "string", "description": "HTTP 方法"}, "url": {"type": "string", "description": "请求 URL"}, "headers": {"type": "object", "description": "请求头"}, "body": {"type": "object", "description": "请求体（JSON）"}, "timeout": {"type": "integer", "default": 30, "description": "超时秒数"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "status_code": {"type": "integer"}, "headers": {"type": "object"}, "body": {"type": "string"}}}', 'medium', 1, 30, 0, '{"readOnlyHint": false, "openWorldHint": true, "idempotentHint": false, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (31, 'image_analyze', '图片分析', '分析图片内容：OCR 文字提取、物体识别、场景描述、图表解读（支持 URL 和本地路径）', 'media', '{"type": "object", "required": ["image"], "properties": {"image": {"type": "string", "description": "图片 URL 或本地路径"}, "prompt": {"type": "string", "default": "描述这张图片", "description": "分析指令"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "description": {"type": "string"}, "text": {"type": "string"}}}', 'low', 1, 60, 0, '{"readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (32, 'web_scrape', '网页结构化提取', '从网页中用 CSS 选择器或 XPath 提取结构化数据（表格、列表、特定元素）', 'web', '{"type": "object", "required": ["url", "selector"], "properties": {"url": {"type": "string", "description": "目标 URL"}, "selector": {"type": "string", "description": "CSS 选择器或 XPath"}, "extract": {"enum": ["text", "html", "attr"], "type": "string", "default": "text", "description": "提取类型"}, "multiple": {"type": "boolean", "default": false, "description": "是否提取所有匹配项"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "results": {"type": "array", "items": {"type": "string"}}, "count": {"type": "integer"}}}', 'low', 1, 30, 0, '{"readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (33, 'translate', '翻译', '多语言翻译（支持中英日韩法德西等 50+ 语言，自动检测源语言）', 'text', '{"type": "object", "required": ["text", "target_lang"], "properties": {"text": {"type": "string", "description": "要翻译的文本"}, "target_lang": {"type": "string", "description": "目标语言代码（如 zh/en/ja/ko）"}, "source_lang": {"type": "string", "description": "源语言代码（可选，自动检测）"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "translated": {"type": "string"}, "source_lang": {"type": "string"}, "target_lang": {"type": "string"}}}', 'low', 1, 15, 0, '{"readOnlyHint": true, "openWorldHint": false, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (34, 'screenshot', '网页截图', '对指定 URL 进行网页截图（支持全页/可视区域，返回 PNG 图片路径）', 'web', '{"type": "object", "required": ["url"], "properties": {"url": {"type": "string", "description": "目标 URL"}, "full_page": {"type": "boolean", "default": false, "description": "是否截取全页"}, "width": {"type": "integer", "default": 1280, "description": "视口宽度"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "path": {"type": "string"}, "width": {"type": "integer"}, "height": {"type": "integer"}}}', 'low', 1, 30, 0, '{"readOnlyHint": true, "openWorldHint": true, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (35, 'audio_transcribe', '语音转文字', '将音频文件转录为文字（支持中英文，支持 WAV/MP3/FLAC 格式）', 'media', '{"type": "object", "required": ["audio"], "properties": {"audio": {"type": "string", "description": "音频文件路径或 URL"}, "language": {"type": "string", "default": "zh", "description": "语言代码"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "text": {"type": "string"}, "duration": {"type": "number"}}}', 'low', 1, 120, 0, '{"readOnlyHint": true, "openWorldHint": false, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (36, 'data_analyze', '数据分析', '对 CSV/JSON 数据进行统计分析（均值/中位数/分布/相关性等）', 'data', '{"type": "object", "required": ["data"], "properties": {"data": {"type": "string", "description": "数据路径（CSV/JSON）或内联数据"}, "analysis": {"enum": ["summary", "distribution", "correlation", "groupby"], "type": "string", "default": "summary", "description": "分析类型"}, "columns": {"type": "array", "items": {"type": "string"}, "description": "指定分析的列"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "result": {"type": "object"}, "row_count": {"type": "integer"}}}', 'low', 1, 60, 0, '{"readOnlyHint": true, "openWorldHint": false, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');
INSERT INTO `tool` VALUES (37, 'code_review', '代码审查', '审查代码质量：语法错误、安全漏洞、性能问题、最佳实践建议', 'code', '{"type": "object", "required": ["code"], "properties": {"code": {"type": "string", "description": "要审查的代码"}, "language": {"type": "string", "description": "编程语言"}, "focus": {"enum": ["security", "performance", "style", "all"], "type": "string", "default": "all", "description": "审查重点"}}}', '{"type": "object", "properties": {"error": {"type": "string"}, "issues": {"type": "array", "items": {"type": "object", "properties": {"line": {"type": "integer"}, "severity": {"type": "string"}, "message": {"type": "string"}}}}, "score": {"type": "integer"}}}', 'low', 1, 30, 0, '{"readOnlyHint": true, "openWorldHint": false, "idempotentHint": true, "destructiveHint": false, "version": "1.0.0"}', 0, '2026-06-27 01:35:00', '2026-06-27 01:35:00');

